// Increment 2: planting and growth.
// p plants a seed on the player's tile: tiles['x,y'] = { crop, stage: 0 } and seeds go down by one.
// t advances one tick: day goes up by one and every planted tile's stage goes up by one until it is grown at stage 3.
// Planted tiles are drawn. Arrow-key movement and everything already working must keep working.

fim.removed:
function plantSeed() {
    const tileKey = `${player.x},${player.y}`;
    if (!tiles[tileKey]) {
        tiles[tileKey] = { crop: 'seed', stage: 1 };
        draw();
    }
}

function advanceTime() {
    day++;
    draw();
}

function harvestCrop() {
    const tileKey = `${player.x},${player.y}`;
    if (tiles[tileKey] && tiles[tileKey].crop === 'seed') {
        tiles[tileKey] = { crop: 'empty', stage: 0 };
        inventory.seeds++;
        inventory.crops--;
        draw();
    }
}

function saveGame() {
    localStorage.setItem('game', JSON.stringify({ player, tiles, inventory, day }));
}

function loadGame() {
    const savedGame = JSON.parse(localStorage.getItem('game'));
    player = savedGame.player;
    tiles = savedGame.tiles;
    inventory = savedGame.inventory;
    day = savedGame.day;
    draw();
}

document.addEventListener('keydown', movePlayer);
document.addEventListener('p', plantSeed);
document.addEventListener('t', advanceTime);
document.addEventListener('h', harvestCrop);
document.addEventListener('s', saveGame);
document.addEventListener('load', loadGame);

